{
  "name": "Test User",
  "email": "test@example.com",
  "password": "Password123!",
  "phone": "01012345678"
}
// Password policy (auth.service.ts): min 8 chars, 1 uppercase, 1 lowercase, 1 number, 1 special (!@#$%^&*), no spaces
// Weak examples that will 400: "password", "password123", "Password123", "password123!"

{
  "email": "test@example.com",
  "password": "Password123!"
}

// Unified login - works for both User and Admin (auth.service.ts:39 checks Admin then User)
// Use any of: email | identifier | username
// Examples:
// Admin: { "email": "admin@esia.local", "password": "Admin123!" }
// User:  { "email": "test@example.com", "password": "Password123!" }
// { "identifier": "test@example.com", "password": "..." }

